var __index = {"config":{"lang":["en"],"separator":"[\\s\\u200b\\u3000\\-\u3001\u3002\uff0c\uff0e\uff1f\uff01\uff1b]+","pipeline":["stemmer"],"fields":{"title":{"boost":1000.0},"text":{"boost":1.0},"tags":{"boost":1000000.0}}},"docs":[{"location":"index.html","title":"\\(Sonri\\) \\(an\\) \\(Sonjo\\) \u5728\u989d\u5c3c\u6cb3\u7554","text":"<p>\u2728\u4f60\u597d\u5440\uff01\u6b22\u8fce\u6765\u5230 \\(\\mathbb{Sonri}\\) \\(\\mathbb{an}\\) \\(\\mathbb{Sonjo}\\) \u7684\u4e2a\u4eba\u7f51\u7ad9\uff0c\u4e00\u4e2a\u7531\u5fae\u7b11\u548c\u68a6\u5883\u7f16\u7ec7\u7684\u6570\u5b57\u82b1\u56ed~~</p> <p>\ud83c\udf90\u6211\u7684\u540d\u5b57 \\(\\mathcal{Sonri}\\) \\(\\mathcal{an}\\) \\(\\mathcal{Sonjo}\\) \u53d6\u81ea\u5fae\u8bed\uff08mini language\uff09\u8bcd\u6c47\u2014\u2014</p> \\(\\mathscr{Sonri}\\) \u5fae\u7b11 \\(\\mathscr{Sonjo}\\) \u68a6\u5883 <p>\ud83d\uddbc\ufe0f\u989d\u5c3c\u6cb3\u662f\u6761\u6e29\u67d4\u3001\u9759\u8c27\u7684\u5c0f\u6eaa\uff0c\u5728\u5409\u7965\u7684\u5c71\u5cad\u4e2d\u81ea\u5728\u5730\u6563\u6b65\u3002\u8fd9\u91cc\u7684\u4eba\u4eec\u5d07\u62dc\u6708\u4eae\u795e\\(\\mathfrak{Beya}\\)\uff0c\u5979\u662f\u6148\u7231\u667a\u6167\u7684\u795e\u660e\uff0c\u4eba\u4eec\u5b89\u7761\u540e\uff0c\u5979\u4f1a\u8f7b\u5de7\u5730\u6765\u5230\u90a3\u4eba\u7684\u8033\u8fb9\u5462\u5583\uff0c\u90a3\u7ec6\u8bed\u6d41\u8fdb\u4e86\u989d\u5c3c\u6cb3\uff0c\u996e\u4e86\u8fd9\u6c34\u7684\u751f\u7075\u4fbf\u5f97\u5230\u4e86\u5979\u7684\u795d\u798f\uff0c\u65f6\u65f6\u4eab\u6709\u5eb7\u5b81\u5eb7\u4e50\u3002</p>"},{"location":"index.html#_1","title":"\u989d\u5c3c\u6cb3\u7684\u6545\u4e8b","text":"<p>\u6765\u5230\u6b64\u5730\u7684\u751f\u8005\u554a\uff0c\u5f52\u5f80\u6545\u4e61\u7684\u884c\u5ba2\u554a\uff0c\u7ec8\u4e00\u65e5\u5bd2\u98ce\u5927\u96ea\u9664\u5374\u4e00\u5207\u751f\u673a\uff0c\u53ea\u6709\u6708\u7684\u667a\u6167\uff0c\u80fd\u5c06\u90a3\u6d88\u6563\u7684\u51dd\u805a\uff0c\u80fd\u5c06\u90a3\u63a9\u6ca1\u7684\u663e\u9732\u3002 \u90a3\u7cbe\u723d\u4e0d\u643a\u8d30\u8005\u82e5\u662f\u6765\u5230\u989d\u5c3c\u6cb3\u7554\uff0c\\(\\mathfrak{Beya}\\)\u4f1a\u548c\u5979\u8bf4\u5c3d\u4e00\u5207\u79d8\u5bc6\u3002</p>"},{"location":"index.html#_2","title":"\u7f51\u7ad9\u5185\u5bb9","text":"<p>\u73b0\u4ee3\u903b\u8f91\u5b66\u4e60\u7b14\u8bb0</p> <p>\u6211\u6b63\u5728\u5b66\u4e60\u73b0\u4ee3\u903b\u8f91\uff0c\u8fd9\u91cc\u4f1a\u9002\u65f6\u6574\u7406\u5e76\u66f4\u65b0\u6211\u7684\u5b66\u4e60\u7b14\u8bb0\uff0c\u8fd1\u671f\u8ba1\u5212\u6db5\u76d6\u4e3b\u9898\u5305\u62ec\uff1a</p> <ul> <li>\u7d20\u6734\u96c6\u5408\u8bba\uff08Naive Set Theory\uff09</li> <li>\u547d\u9898\u903b\u8f91\uff08Propositional Logic\uff09</li> <li>\u4e00\u9636\u903b\u8f91\uff08First-order Logic\uff09</li> <li>\u547d\u9898\u6a21\u6001\u903b\u8f91\uff08Modal Logic\uff09</li> <li>\u4ea4\u66ff\u65f6\u6001\u903b\u8f91\uff08Alternating-time Temporal Logic\uff09</li> </ul> <p>-------------------------------------------</p> <p>\u8eab\u5728\u5b87\u5b99\u4e00\u9685\uff0c\u4e5f\u6709\u7e41\u661f\u4f5c\u4f34\u3002</p> <p>\u5efa\u7ad9\u65f6\u95f4\uff1a2026/9/9 22:26(GMT+8:00)</p>"},{"location":"ATL/index.html","title":"\u4ea4\u66ff\u65f6\u6001\u903b\u8f91","text":""},{"location":"ATL/syntax_and_semantics.html","title":"\u8bed\u6cd5\u548c\u8bed\u4e49","text":"\u76ee\u5f55<ul> <li>\u8bed\u6cd5\u548c\u8bed\u4e49<ul> <li>\u6a21\u578b</li> <li>\u8bed\u6cd5</li> <li>\u8bed\u4e49</li> </ul> </li> </ul>"},{"location":"ATL/syntax_and_semantics.html#_2","title":"\u6a21\u578b","text":"<p>\u5b9a\u4e491.1\uff08\u5e76\u53d1\u535a\u5f08\u7ed3\u6784\uff0cCGS\uff09 \u2002\u4ea4\u66ff\u65f6\u6001\u903b\u8f91\u5b9a\u4e49\u5728\u5e26\u540d\u79f0\u7684\u5e76\u53d1\u535a\u5f08\u7ed3\u6784\uff08Concurrent Game Structure\uff0cCGS\uff09\u4e0a\uff0c\u4e00\u4e2aCGS\u662f\u4e00\u4e2a\u4e03\u5143\u7ec4\\(\\mathcal{S} = \\langle \\Sigma, \\mathcal{Q}, \\Pi,\\pi, \\mathcal{A}ct,d,\\delta\\rangle\\):</p> <p>- \\(\\Sigma=\\{a_1,a_2,\\ldots,a_n\\}\\)\u662f\u6709\u9650\u975e\u7a7a\u7684\u5168\u4f53\u73a9\u5bb6\u96c6\uff0c\u7528\\(a_i\\)\u8868\u793a\\(\\Sigma\\)\u4e2d\u7684\u4efb\u610f\u5143\u7d20\uff1b</p> <p>- \\(\\mathcal{Q}\\)\u662f\u975e\u7a7a\u7684\u72b6\u6001\u96c6\uff0c\u7528\\(q\\)\u8868\u793a\\(\\mathcal{Q}\\)\u4e2d\u7684\u4efb\u610f\u5143\u7d20\uff1b</p> <p>- \\(\\Pi\\)\u662f\u539f\u5b50\u547d\u9898\u96c6\uff0c\u7528\\(p\\)\u8868\u793a\\(\\Pi\\)\u4e2d\u7684\u4efb\u610f\u5143\u7d20\uff1b</p> <p>- \\(\\pi\\colon\\mathcal{Q}\\longrightarrow2^{\\Pi}\\)\u662f\u8d4b\u503c\u51fd\u6570\uff0c\u5c06\u72b6\u6001\\(q\\)\u6620\u5c04\u81f3\u539f\u5b50\u547d\u9898\u96c6\\(\\Pi\\)\u7684\u5b50\u96c6\\(\\pi(q)\\)\u4e0a\uff0c\u8868\u793a\u5728\u72b6\u6001\\(q\\)\u4e0a\u53d6\u503c\u4e3a\u771f\u7684\u4e00\u7ec4\u539f\u5b50\u547d\u9898\uff1b</p> <p>- \\(\\mathcal{A}ct\\)\u662f\u975e\u7a7a\u7684\u5168\u4f53\u884c\u52a8\u96c6\uff0c\u7528\\(\\alpha\\)\u8868\u793a\\(\\mathcal{A}ct\\)\u4e2d\u7684\u4efb\u610f\u5143\u7d20\uff1b</p> <p>- \\(d\\colon\\mathcal{Q}\\times\\Sigma\\longrightarrow2^{\\mathcal{A}ct}\\setminus\\{\\emptyset\\}\\)\u662f\u53ef\u884c\u884c\u52a8\u51fd\u6570\uff0c\u5b83\u5c06\u72b6\u6001\\(q\\)\u548c\u73a9\u5bb6\\(a_i\\)\u6620\u5c04\u81f3\u5168\u4f53\u884c\u52a8\u96c6\\(\\mathcal{A}ct\\)\u7684\u975e\u7a7a\u5b50\u96c6\\(d_{a_i}(q)\\)\u4e0a\uff0c\u8868\u793a\u5728\u72b6\u6001\\(q\\)\u4e0a\u73a9\u5bb6\\(a\\)\u6240\u6709\u53ef\u9009\u53d6\u7684\u884c\u52a8\uff1b\u5168\u4f53\u73a9\u5bb6\u5728\u72b6\u6001\\(q\\)\u4e0b\u7684\u53ef\u884c\u884c\u52a8\u5411\u91cf\u96c6\\(D(q)=\\mathop{\\times}\\limits_{a_i\\in\\Sigma}  d_{a_i}(q)\\)\uff0c\u6613\u77e5\\(D(q)\\subseteq\\mathcal{A}ct^\\Sigma\\)\uff1b\u5728\u72b6\u6001\\(q\\)\u4e0b\u7684\u884c\u52a8\u5411\u91cf\\(\\vec{\\alpha}=\\langle\\alpha_{a_1},\\alpha_{a_2},\\ldots,\\alpha_{a_n}\\rangle\\in D(q)\\)\u4e3a\u5168\u4f53\u73a9\u5bb6\u5728\u72b6\u6001\\(q\\)\u4e0b\u5206\u522b\u5206\u914d\u4e86\u4e00\u4e2a\u8be5\u73a9\u5bb6\u7684\u53ef\u884c\u884c\u52a8\uff1b</p> <p>- \\(\\delta\\)\u662f\u72b6\u6001\u8fc1\u79fb\u51fd\u6570\uff0c\u5b83\u5c06\u4e00\u4e2a\u72b6\u6001\\(q\\)\u548c\u5728\u8be5\u72b6\u6001\u4e0b\u7684\u4e00\u4e2a\u884c\u52a8\u5411\u91cf\\(\\vec{\\alpha}=\\langle\\alpha_{a_1},\\alpha_{a_2},\\ldots,\\alpha_{a_n}\\rangle\\in D(q)\\)\u6620\u5c04\u81f3\u72b6\u6001\\(\\delta(q,\\alpha_{a_1},\\alpha_{a_2},\\ldots,\\alpha_{a_n})\\)\u4e0a\uff0c\u8868\u793a\u72b6\u6001\\(q\\)\u4e0b\u6bcf\u4f4d\u73a9\u5bb6\\(a_i\\)\u5206\u522b\u91c7\u53d6\u884c\u52a8\\(\\alpha_{a_i}\\)\u540e\uff0c\u5c06\u8fc1\u79fb\u6216\u62b5\u8fbe\u7684\u72b6\u6001\uff1b\u82e5\\(\\vec{\\alpha}=\\langle\\alpha_{a_1},\\alpha_{a_2},\\ldots,\\alpha_{a_n}\\rangle\\not\\in D(q)\\)\uff0c\u5219\\(\\delta(q,\\alpha_{a_1},\\alpha_{a_2},\\ldots,\\alpha_{a_n})\\)\u65e0\u5b9a\u4e49\uff1b\\(\\delta(q,D(q))=\\{\\delta(q,\\vec{\\alpha})\\mid\\vec{\\alpha}\\in D(q)\\}\\)\u8868\u793a\u72b6\u6001\\(q\\)\u7684\u6240\u6709\u540e\u7ee7\u72b6\u6001\u6784\u6210\u7684\u96c6\u5408\uff1b</p> <p>\u65e0\u8bb0\u5fc6\u7b56\u7565 \u2002\u51fd\u6570\\(f_a\\colon\\mathcal{Q}\\longrightarrow\\mathcal{A}ct\\)\u662f\u73a9\u5bb6\\(a\\)\u7684\u4e00\u4e2a\u65e0\u8bb0\u5fc6\u7b56\u7565\uff0c\u5176\u4e2d\u8be5\u51fd\u6570\u7684\u6240\u6709\u53d6\u503c\\(f_a(q)\\in d_a(q)\\)\uff0c\u8be5\u51fd\u6570\u4e3a\u73a9\u5bb6\\(a\\)\u5728\u6240\u6709\u72b6\u6001\u4e0b\u90fd\u6307\u6d3e\u4e86\u4e00\u4e2a\u53ef\u884c\u884c\u52a8\u3002\u5bf9\u4e8e\u8054\u76df\\(A\\subseteq\\Sigma\\)\u548c\u73a9\u5bb6\\(a\\in A\\)\uff0c\u51fd\u6570\\(F_A:a\\longmapsto f_a\\)\u8868\u793a\u8054\u76df\\(A\\)\u7684\u65e0\u8bb0\u5fc6\u7b56\u7565\uff0c\u8be5\u51fd\u6570\u4e3a\u8054\u76df\\(A\\)\u4e2d\u7684\u6bcf\u4f4d\u73a9\u5bb6\\(a\\)\u90fd\u6307\u6d3e\u4e86\u4e00\u4e2a\u7b56\u7565\u3002</p> <p>\u8ba1\u7b97\u8def\u5f84\u548c\u8f93\u51fa\u51fd\u6570 \u2002\u8ba1\u7b97\u8def\u5f84\\(\\lambda=q_0,q_1,q_2,\\ldots\\)\u662f\u4e00\u4e2a\u72b6\u6001\u53d8\u5316\u5e8f\u5217\uff0c\u5176\u4e2d\u5bf9\u4e8e\u6240\u6709\\(i\\geq 0\\)\uff0c\\(q_{i+1}\\in\\delta(q_i,D(q_i))\\)\uff1b\u7ea6\u5b9a\\(\\lambda[i]=q_i\\)\uff0c\\(\\lambda[i,j]=q_i,q_{i+1},\\ldots,q_j\\)\uff0c\\(\\lambda[i,\\infty]=q_i,q_{i+1},\\ldots\\)\u3002\u8f93\u51fa\u51fd\u6570\\(out(q,F_A)=\\{\\lambda=q_0,q_1,q_2,\\ldots\\mid q_0=q\\)\u5e76\u4e14\\(q_{i+1}=\\delta(q_i,\\vec{\\alpha}),\\)\u5176\u4e2d\\(\\vec{\\alpha}=\\langle\\alpha_{a_1},\\alpha_{a_2},\\ldots,\\alpha_{a_n}\\rangle\\in D(q_i)\\)\u5e76\u4e14\u5bf9\u4e8e\u6240\u6709\u7684\\(a_i\\in A,\\alpha_{a_i}=F_A(a_i)(q_i)\\}\\)\u3002\u8fd9\u4e00\u8f93\u51fa\u51fd\u6570\u7684\u5143\u7d20\u5305\u62ec\u8054\u76df\\(A\\)\u9075\u5faa\u7b56\u7565\\(F_A\\)\u53ef\u4fdd\u8bc1\u7684\u6240\u6709\u8def\u5f84\u3002</p>"},{"location":"ATL/syntax_and_semantics.html#_3","title":"\u8bed\u6cd5","text":"<p>\u5b9a\u4e491.2\uff08ATL\u8bed\u6cd5\uff09 \u2002\u7ed9\u5b9a\u4e00\u4e2a\u539f\u5b50\u547d\u9898\u96c6\\(\\Pi\\)\u548c\u4e00\u4e2a\u5168\u4f53\u73a9\u5bb6\u96c6\\(\\Sigma\\)\uff0c\\(\\mathcal{L}_{ATL}\\)\u7684\u8bed\u6cd5\u5b9a\u4e49\u5982\u4e0b\uff1a</p> \\[ \\varphi ::=  p \\mid \\neg\\varphi \\mid \\varphi_1 \\lor \\varphi_2 \\mid \\langle\\!\\langle A\\rangle\\!\\rangle\\bigcirc\\varphi \\mid \\langle\\!\\langle A\\rangle\\!\\rangle \\Box \\varphi \\mid \\langle\\!\\langle A\\rangle\\!\\rangle \\varphi_1 \\mathcal{U} \\varphi_2 \\\\ \\] <p>\u5176\u4e2d\\(p\\in\\Pi\\)\uff0c\\(A\\subseteq\\Sigma\\)\u3002\\(\\langle\\!\\langle \\cdot\\rangle\\!\\rangle\\)\u662f\u8054\u76df\u8def\u5f84\u91cf\u8bcd\uff0c \\(\\Box\\text{\u3001}\\bigcirc\\)\u548c\\(\\mathcal{U}\\)\u662f\u65f6\u6001\u7b97\u5b50\uff0c\\(\\neg\\)\u548c\\(\\lor\\)\u662f\u5e03\u5c14\u7b97\u5b50\u3002</p> <p>\u5e03\u5c14\u7b97\u5b50\\(\\land\\)\u3001\\(\\to\\)\u548c\\(\\leftrightarrow\\)\uff0c\u96f6\u5143\u8054\u7ed3\u8bcd\uff08\u903b\u8f91\u5e38\u91cf\uff09\\(\\top\\)\u548c\\(\\bot\\)\uff0c\u4ee5\u53ca\u6d89\u53ca\u65f6\u6001\u7b97\u5b50\\(\\Diamond\\)\u7684\u8054\u76df\u516c\u5f0f\u53ef\u5b9a\u4e49\u5982\u4e0b\uff1a</p> \\[ \\begin{align*} \\varphi_1\\land\\varphi_2\\equiv&amp;\\neg(\\neg\\varphi_1\\lor\\neg\\varphi_2)\\\\\\varphi_1\\to\\varphi_2\\equiv&amp; \\neg\\varphi_1\\lor\\varphi_2\\\\\\varphi_1\\leftrightarrow\\varphi_2\\equiv&amp; (\\varphi_1\\to\\varphi_2)\\land(\\varphi_2\\to\\varphi_1)\\\\\\top\\equiv&amp;\\varphi\\lor\\neg\\varphi\\\\\\bot\\equiv&amp;\\neg\\top\\\\\\langle\\!\\langle A\\rangle\\!\\rangle\\Diamond\\varphi\\equiv&amp;\\langle\\!\\langle A\\rangle\\!\\rangle\\top\\mathcal{U}\\varphi\\ \\end{align*} \\]"},{"location":"ATL/syntax_and_semantics.html#_4","title":"\u8bed\u4e49","text":"<p>\u5b9a\u4e491.3\uff08ATL\u8bed\u4e49\uff09 \u2002ATL\u7684\u8bed\u4e49\u5b9a\u4e49\u5728CGS \\(\\mathcal{S}\\)\u4e0a\uff0c\\(\\mathcal{S},q\\models\\varphi\\)\u8868\u660e\u7ed3\u6784\\(\\mathcal{S}\\)\u4e0a\u7684\u72b6\u6001\\(q\\)\u6ee1\u8db3\u72b6\u6001\u516c\u5f0f\\(\\varphi\\)\uff0c\u4ee4\u51fd\u6570\\([n]=\\{0,1,\\ldots,n-1\\}\\)\uff08\\(n\\in\\mathbb{N}\\)\uff09\uff0c\u6ee1\u8db3\u5173\u7cfb\\(\\models\\)\u5b9a\u4e49\u5982\u4e0b\uff1a</p> <p>- \\(\\mathcal{S},q\\models p\\) \u5f53\u4e14\u4ec5\u5f53 \\(p\\in\\pi(q)\\)\uff1b</p> <p>- \\(\\mathcal{S},q\\models\\neg\\varphi\\) \u5f53\u4e14\u4ec5\u5f53 \\(\\mathcal{S},q\\not\\models\\varphi\\)\uff1b</p> <p>- \\(\\mathcal{S},q\\models\\varphi_1\\lor\\varphi_2\\) \u5f53\u4e14\u4ec5\u5f53 \\(\\mathcal{S},q\\models\\varphi_1\\)\u6216\u8005\\(\\mathcal{S},q\\models\\varphi_2\\)\uff1b</p> <p>- \\(\\mathcal{S},q \\models\\langle\\!\\langle A\\rangle\\!\\rangle\\bigcirc\\varphi\\) \u5f53\u4e14\u4ec5\u5f53 \u5b58\u5728\\(F_A\\)\uff0c\u4f7f\u5f97\u5bf9\u4e8e\u6240\u6709\u7684\\(\\lambda\\in out(q,F_A)\\)\uff0c\\(\\mathcal{S},\\lambda[1]\\models\\varphi\\)\uff1b</p> <p>- \\(\\mathcal{S},q \\models\\langle\\!\\langle A\\rangle\\!\\rangle\\Box \\varphi\\) \u5f53\u4e14\u4ec5\u5f53 \u5b58\u5728\\(F_A\\)\uff0c\u4f7f\u5f97\u5bf9\u4e8e\u6240\u6709\u7684\\(\\lambda\\in out(q,F_A)\\)\uff0c\u5bf9\u4e8e\u6240\u6709\u7684\\(i\\in\\mathbb{N}\\)\uff0c\\(\\mathcal{S},\\lambda[i]\\models\\varphi\\)\uff1b</p> <p>- \\(\\mathcal{S},q \\models\\langle\\!\\langle A\\rangle\\!\\rangle\\varphi_1\\mathcal{U}\\varphi_2\\) \u5f53\u4e14\u4ec5\u5f53 \u5b58\u5728\\(F_A\\)\uff0c\u4f7f\u5f97\u5bf9\u4e8e\u6240\u6709\u7684\\(\\lambda\\in out(q,F_A)\\)\uff0c\u5b58\u5728\\(i\\in \\mathbb{N}\\)\u4f7f\u5f97\\(\\mathcal{S},\\lambda[i]\\models\\varphi_2\\)\uff0c\u5e76\u4e14\u5bf9\u4e8e\u6240\u6709\u7684\\(j\\in[i]\\)\uff0c\\(\\mathcal{S},\\lambda[j]\\models\\varphi_1\\).</p>"},{"location":"Prerequisites/index.html","title":"\u9884\u5907\u77e5\u8bc6","text":"<p>\u73b0\u4ee3\u903b\u8f91\uff08\u7b26\u53f7\u903b\u8f91\uff09\u662f\u9ad8\u5ea6\u5f62\u5f0f\u5316\u7b26\u53f7\u5316\u7684\u5b66\u79d1\uff0c\u5b66\u4e60\u73b0\u4ee3\u903b\u8f91\u9700\u8981\u4e00\u4e9b\u9884\u5907\u77e5\u8bc6\uff0c\u6bd4\u5982\u6570\u5b66\u65b9\u6cd5\u3001\u7d20\u6734\u96c6\u5408\u8bba\u3001\u5f62\u5f0f\u8bed\u8a00\u4e0e\u5143\u903b\u8f91\u57fa\u7840\uff0c\u672c\u90e8\u5206\u7684\u7b14\u8bb0\u5c06\u4f9d\u6b21\u4ecb\u7ecd\u8fd9\u4e9b\u77e5\u8bc6\u3002\u8fd9\u4e9b\u77e5\u8bc6\u662f\u96f6\u57fa\u7840\u7684\uff0c\u4e0d\u8fc7\u5982\u679c\u8bfb\u8005\u6709\u5b66\u4e60\u9ad8\u4e2d\u6570\u5b66\u7684\u7ecf\u9a8c\u3001\u63a5\u89e6\u8fc7\u4e00\u4e9b\u666e\u901a\u903b\u8f91\u77e5\u8bc6\uff0c\u90a3\u4e48\u7406\u89e3\u8d77\u6765\u5c31\u4f1a\u76f8\u5bf9\u5bb9\u6613\u4e00\u4e9b\u3002\u4e0d\u8fc7\u9700\u8981\u5f3a\u8c03\u7684\u662f\uff0c\u8fd9\u4e9b\u56db\u4e2a\u9886\u57df\u7684\u77e5\u8bc6\u67d0\u79cd\u7a0b\u5ea6\u4e0a\u662f\u76f8\u4e92\u4f9d\u8d56\u7684\uff0c\u6bd4\u5982\u7d20\u6734\u96c6\u5408\u8bba\u4e2d\u4e00\u4e9b\u8bc1\u660e\u9700\u8981\u8bfb\u8005\u4e86\u89e3\u6570\u5b66\u8bc1\u660e\u65b9\u6cd5\uff0c\u800c\u6570\u5b66\u8bc1\u660e\u65b9\u6cd5\u4e2d\u4e00\u4e9b\u65b9\u6cd5\u7684\u4ecb\u7ecd\u4e5f\u9700\u8981\u7d20\u6734\u96c6\u5408\u8bba\u6240\u4f7f\u7528\u7684\u7b26\u53f7\uff0c\u672c\u7b14\u8bb0\u5c06\u4f1a\u5728\u5404\u7bc7\u7ae0\u5f00\u59cb\u5904\u8bf4\u660e\u9605\u8bfb\u672c\u7ae0\u524d\u5efa\u8bae\u9605\u8bfb\u7684\u5185\u5bb9\uff0c\u5728\u5404\u7bc7\u7ae0\u7ed3\u5c3e\u5904\u8bf4\u660e\u9605\u8bfb\u4e0b\u4e00\u7ae0\u524d\u5efa\u8bae\u9605\u8bfb\u7684\u5185\u5bb9\u3002 \u6b64\u5916\uff0c\u5b66\u4e60\u73b0\u4ee3\u903b\u8f91\u7684\u7279\u5b9a\u5206\u652f\u53ef\u80fd\u9700\u8981\u4e00\u4e9b\u9488\u5bf9\u6027\u7684\u9884\u5907\u77e5\u8bc6\uff0c\u6bd4\u5982\u5b66\u4e60\u6a21\u6001\u903b\u8f91\u53ef\u80fd\u9700\u8981\u4e86\u89e3\u4e00\u4e9b\u56fe\u8bba\u548c\u5206\u6790\u5f62\u800c\u4e0a\u5b66\uff0c\u5b66\u4e60\u4ea4\u66ff\u65f6\u6001\u903b\u8f91\u53ef\u80fd\u9700\u8981\u4e86\u89e3\u4e00\u4e9b\u535a\u5f08\u8bba\uff0c\u8fd9\u4e9b\u77e5\u8bc6\u5c06\u5728\u76f8\u5e94\u677f\u5757\u4e88\u4ee5\u4ecb\u7ecd\u3002</p> \u76ee\u5f55<ul> <li>\u9884\u5907\u77e5\u8bc6<ul> <li>\u6570\u5b66\u65b9\u6cd5</li> <li>\u7d20\u6734\u96c6\u5408\u8bba</li> <li>\u5f62\u5f0f\u8bed\u8a00\u4e0e\u5143\u903b\u8f91\u57fa\u7840</li> </ul> </li> </ul>"},{"location":"Prerequisites/index.html#_2","title":"\u6570\u5b66\u65b9\u6cd5","text":""},{"location":"Prerequisites/index.html#_3","title":"\u7d20\u6734\u96c6\u5408\u8bba","text":""},{"location":"Prerequisites/index.html#_4","title":"\u5f62\u5f0f\u8bed\u8a00\u4e0e\u5143\u903b\u8f91\u57fa\u7840","text":""},{"location":"Prerequisites/basic_formal_language_and_metalogic.html","title":"\u5f62\u5f0f\u8bed\u8a00\u4e0e\u5143\u903b\u8f91\u57fa\u7840","text":"\u76ee\u5f55<ul> <li>\u5f62\u5f0f\u8bed\u8a00\u4e0e\u5143\u903b\u8f91\u57fa\u7840<ul> <li>\u5f62\u5f0f\u8bed\u8a00</li> <li>\u6587\u6cd5\u4e0e\u751f\u6210</li> <li>\u8bed\u6cd5\u6811\u4e0e\u552f\u4e00\u53ef\u8bfb\u6027</li> <li>\u903b\u8f91\u540e\u627f\u53ca\u5176\u6784\u9020</li> <li>\u7814\u7a76\u4e0e\u5e94\u7528</li> </ul> </li> </ul>"},{"location":"Prerequisites/basic_formal_language_and_metalogic.html#_2","title":"\u5f62\u5f0f\u8bed\u8a00","text":""},{"location":"Prerequisites/basic_formal_language_and_metalogic.html#_3","title":"\u6587\u6cd5\u4e0e\u751f\u6210","text":""},{"location":"Prerequisites/basic_formal_language_and_metalogic.html#_4","title":"\u8bed\u6cd5\u6811\u4e0e\u552f\u4e00\u53ef\u8bfb\u6027","text":""},{"location":"Prerequisites/basic_formal_language_and_metalogic.html#_5","title":"\u903b\u8f91\u540e\u627f\u53ca\u5176\u6784\u9020","text":""},{"location":"Prerequisites/basic_formal_language_and_metalogic.html#_6","title":"\u7814\u7a76\u4e0e\u5e94\u7528","text":""},{"location":"Prerequisites/mathematical_method.html","title":"\u6570\u5b66\u65b9\u6cd5","text":"\u76ee\u5f55<ul> <li>\u6570\u5b66\u65b9\u6cd5<ul> <li>\u6570\u5b66\u5b9a\u4e49</li> <li>\u6570\u5b66\u547d\u9898</li> <li>\u6570\u5b66\u8bc1\u660e</li> <li>\u516c\u7406\u4e0e\u5b9a\u7406</li> <li>\u903b\u8f91\u4e0e\u76f4\u89c9</li> </ul> </li> </ul>"},{"location":"Prerequisites/mathematical_method.html#_2","title":"\u6570\u5b66\u5b9a\u4e49","text":""},{"location":"Prerequisites/mathematical_method.html#_3","title":"\u6570\u5b66\u547d\u9898","text":""},{"location":"Prerequisites/mathematical_method.html#_4","title":"\u6570\u5b66\u8bc1\u660e","text":""},{"location":"Prerequisites/mathematical_method.html#_5","title":"\u516c\u7406\u4e0e\u5b9a\u7406","text":""},{"location":"Prerequisites/mathematical_method.html#_6","title":"\u903b\u8f91\u4e0e\u76f4\u89c9","text":""},{"location":"Prerequisites/naive_set_theory_1.html","title":"\u7d20\u6734\u96c6\u5408\u8bba","text":"\u76ee\u5f55<ul> <li>\u7d20\u6734\u96c6\u5408\u8bba<ul> <li>I. \u516c\u7406\u548c\u7c7b<ul> <li>1. \u7c7b\u3001\u96c6\u5408\u4e0e\u516c\u7406<ul> <li>1.1 \u77db\u76fe\u9648\u8ff0</li> <li>1.2 \u96c6\u5408</li> <li>1.3 \u516c\u7406\u7cfb\u7edf</li> </ul> </li> </ul> </li> </ul> </li> </ul>"},{"location":"Prerequisites/naive_set_theory_1.html#i","title":"I. \u516c\u7406\u548c\u7c7b","text":""},{"location":"Prerequisites/naive_set_theory_1.html#1","title":"1. \u7c7b\u3001\u96c6\u5408\u4e0e\u516c\u7406","text":""},{"location":"Prerequisites/naive_set_theory_1.html#11","title":"1.1 \u77db\u76fe\u9648\u8ff0","text":"<ul> <li> <p>\u6570\u5b66\u9648\u8ff0\uff08statement\uff09\uff1a\u6709\u771f\u5047\u503c\u7684\u5ba3\u79f0\u3002\u771f\u503c\uff08true\uff09\u548c\u5047\u503c\uff08false\uff09\u76f8\u6392\u65a5\uff08\u4e00\u4e2a\u9648\u8ff0\u662f\u771f\u7684\uff0c\u90a3\u5b83\u5c31\u4e0d\u662f\u5047\u7684\uff0c\u53cd\u4e4b\u4ea6\u7136\uff09\u3002 \u5148\u51b3\u7684\u903b\u8f91\u89c4\u5219\uff1a\u88ab\u7528\u6765\u5e2e\u52a9\u786e\u5b9a\u9648\u8ff0\u771f\u5047\u7684\uff0c\u5df2\u786e\u5b9a\u771f\u5047\u7684\u6570\u5b66\u9648\u8ff0\u53ef\u7ecf\u7ec4\u5408\u903b\u8f91\u5730\u786e\u5b9a\u5176\u4ed6\u4e00\u4e9b\u6570\u5b66\u9648\u8ff0\u7684\u771f\u5047\u3002\u57fa\u672c\u903b\u8f91\u89c4\u5219\u5fc5\u987b\u5f97\u5230\u9075\u5b88\uff0c\u5426\u5219\u8bba\u8bc1\u5c31\u88ab\u8bc4\u4ef7\u4e3a\u201c\u4e0d\u5408\u903b\u8f91\u201d\u3002</p> </li> <li> <p>\u6570\u5b66\u8bba\u8bc1\uff08argument\uff09/\u6f14\u7ece\uff08deduction\uff09\uff1a\u6570\u5b66\u9648\u8ff0\u6309\u7ecf\u903b\u8f91\u89c4\u5219\u786e\u5b9a\u771f\u5047\u7684\u5148\u540e\u987a\u5e8f\u6392\u5217\u7684\u7cfb\u7edf\uff0c\u7531\u4e8e\u903b\u8f91\u89c4\u5219\u7684\u7ec4\u7ec7\u6392\u5217\uff0c\u8fd9\u4e00\u7cfb\u7edf\u662f\u4e25\u8c28\u7684\u3002</p> </li> <li> <p>\u81ea\u660e\uff08self-evident\uff09\u9648\u8ff0\uff1a\u5728\u8bc1\u660e\u7cfb\u7edf\u4e2d\uff0c\u6700\u5f00\u59cb\u7684\u6570\u5b66\u9648\u8ff0\u4e0d\u80fd\u88ab\u5176\u4ed6\u6570\u5b66\u9648\u8ff0\u8bc1\u660e\uff0c\u5b83\u7684\u771f\u5047\u503c\u57fa\u4e8e\u5e38\u8bc6\uff08common sense\uff09\u800c\u5ba3\u79f0\u3002</p> </li> <li> <p>\u8bba\u57df\uff1a\u7ed9\u51fa\u7684\u786e\u5b9a\u7684\u81ea\u8bc1\u9648\u8ff0\u96c6\uff08\\(\\mathscr{A}\\)\uff09\u548c\u4e00\u7cfb\u5217\u903b\u8f91\u89c4\u5219\uff0c\u5c31\u786e\u5b9a\u4e86\u6240\u6709\u53ef\u4ece\u81ea\u660e\u9648\u8ff0\u96c6\u63a8\u5bfc\u51fa\u4e3a\u771f\u7684\u9648\u8ff0\uff0c\u8fd9\u4e9b\u9648\u8ff0\u6784\u6210\u8bba\u57df\uff08\\(\\mathscr{U}_\\mathscr{A}\\)\uff09\uff0c\u4e00\u4e2a\u8bba\u57df\u53ef\u6784\u5efa\u4e00\u95e8\u4f9b\u63a2\u7d22\u53d1\u73b0\u7684\u6570\u5b66\u7406\u8bba\u3002</p> </li> <li> <p>\u77db\u76fe\u9648\u8ff0\uff08contradictory statment\uff09/\u6096\u8bba\uff08paradox\uff09\uff1a\u4e00\u4e2a\u65e2\u88ab\u786e\u5b9a\u4e3a\u771f\u53c8\u88ab\u786e\u5b9a\u4e3a\u5047\u7684\u9648\u8ff0\u3002\u5982\u679c\u4ece\u4e00\u4e2a\u88ab\u89c6\u4f5c\u65e0\u77db\u76fe\u7684\u81ea\u660e\u9648\u8ff0\u4e2d\u903b\u8f91\u5730\u5f97\u51fa\u6096\u8bba\uff0c\u5219\u9700\u8981\u68c0\u67e5\u5bfc\u81f4\u6096\u8bba\u7684\u5047\u8bbe\u3002</p> </li> </ul> <p>\u751f\u8bcd\uff1avice-versa\u53cd\u4e4b\u4ea6\u7136\uff1belaborate\u8be6\u5c3d\u7684\uff1bscrutiny\u4ed4\u7ec6\u68c0\u67e5\uff1brenegade\u53db\u5f92\uff1bingenuity\u806a\u660e\u624d\u667a</p>"},{"location":"Prerequisites/naive_set_theory_1.html#12","title":"1.2 \u96c6\u5408","text":"<ul> <li>\u7d20\u6734\u7684\u96c6\u5408\u7406\u89e3\uff1a</li> </ul> <p>\uff081\uff09\u96c6\u5408\u5b8c\u5168\u7531\u5b83\u7684\u5143\u7d20\u51b3\u5b9a\uff0c\u4e24\u4e2a\u96c6\u5408\u76f8\u7b49\u5f53\u4e14\u4ec5\u5f53\u5b83\u4eec\u5177\u6709\u76f8\u540c\u7684\u5143\u7d20\u3002[re\uff1a\u5916\u5ef6\u516c\u7406\uff1a\\(\\forall A \\forall B (\\forall x (x \\in A \\leftrightarrow x \\in B) \\rightarrow A = B)\\)]</p> <p>\uff082\uff09\u96c6\u5408\u7531\u5b83\u5143\u7d20\u6240\u5206\u4eab\u7684\u6027\u8d28\u5b9a\u4e49\uff0c\u8fd9\u4e2a\u6027\u8d28\u662f\u65e0\u6a21\u7cca\u88ab\u826f\u597d\u8868\u8ff0\u7684\uff0c\u4ee5\u81f3\u4e8e\u53ef\u4ee5\u660e\u786e\u5224\u65ad\u4e00\u4e2a\u7ed9\u51fa\u7684\u5143\u7d20\u662f\u5426\u5c5e\u4e8e\u8be5\u96c6\u5408\u3002[\\(\\exists B \\forall x (x \\in B \\leftrightarrow \\varphi(x))\\)]</p> <p>\u201c\u662f\u4e00\u4e2a\u96c6\u5408\u201d\u4e5f\u662f\u4e00\u79cd\u6027\u8d28\uff0c\u6240\u4ee5\u5b58\u5728\u5173\u4e8e\u96c6\u5408\u7684\u96c6\u5408\u3002</p> <ul> <li>\u7f57\u7d20\u6096\u8bba\uff1a\u96c6\u5408\\(R\\)\u662f\u6240\u6709\u201c\u4e0d\u662f\u81ea\u8eab\u5143\u7d20\u7684\u96c6\u5408\u201d\u6784\u6210\u7684\u96c6\u5408\u3002\u5982\u679c\\(R\\)\u5c5e\u4e8e\u6240\u6709\u201c\u4e0d\u662f\u81ea\u8eab\u5143\u7d20\u7684\u96c6\u5408\u201d\u6784\u6210\u7684\u96c6\u5408\uff0c\u90a3\u4e48\\(R\\)\u5177\u6709\u201c\u4e0d\u662f\u81ea\u8eab\u5143\u7d20\u7684\u96c6\u5408\u201d\u8fd9\u4e00\u6027\u8d28\uff0c\\(R\\)\u4e0d\u5c5e\u4e8e\u5b83\u81ea\u8eab\uff0c\u5373\u4e0d\u5c5e\u4e8e\u6240\u6709\u201c\u4e0d\u662f\u81ea\u8eab\u5143\u7d20\u7684\u96c6\u5408\u201d\u6784\u6210\u7684\u96c6\u5408\uff1b\u5982\u679c\\(R\\)\u4e0d\u5c5e\u4e8e\u6240\u6709\u201c\u4e0d\u662f\u81ea\u8eab\u5143\u7d20\u7684\u96c6\u5408\u201d\u6784\u6210\u7684\u96c6\u5408\uff0c\u90a3\u4e48\\(R\\)\u4e0d\u5c5e\u4e8e\u5b83\u81ea\u8eab\uff0c\u56e0\u800c\u5177\u6709\u201c\u4e0d\u662f\u81ea\u8eab\u5143\u7d20\u7684\u96c6\u5408\u201d\u8fd9\u4e00\u6027\u8d28\uff0c\u6240\u4ee5\\(R\\)\u5c5e\u4e8e\u6240\u6709\u201c\u4e0d\u662f\u81ea\u8eab\u5143\u7d20\u7684\u96c6\u5408\u201d\u6784\u6210\u7684\u96c6\u5408\u3002\u201c\u6240\u6709\u2018\u4e0d\u662f\u81ea\u8eab\u5143\u7d20\u7684\u96c6\u5408\u2019\u6784\u6210\u7684\u96c6\u5408\u5c5e\u4e8e\u6240\u6709\u2018\u4e0d\u662f\u81ea\u8eab\u5143\u7d20\u7684\u96c6\u5408\u2019\u6784\u6210\u7684\u96c6\u5408\u201d\u662f\u4e00\u4e2a\u6096\u8bba\u3002[re\uff1a\\(R=\\{x\\mid x\\not\\in x\\}\\text{;}R\\in R\\leftrightarrow R\\not\\in R \\Rightarrow \\bot\\)]</li> </ul> <p>\u662f\u54ea\u4e9b\u9519\u8bef\u7684\u5047\u8bbe\u5bfc\u81f4\u4e86\u8fd9\u4e00\u6096\u8bba\uff1f\u8bb8\u591a\u6570\u5b66\u5bb6\u5f00\u59cb\u8ffd\u6eaf\u5230\u201c\u96c6\u5408\u201d\u8fd9\u4e00\u6982\u5ff5\uff0c\u8be5\u95ee\u9898\u572820\u4e16\u7eaa\u521d\u5177\u6709\u9ad8\u4f18\u5148\u6743\uff0c\u5e76\u53d1\u5c55\u51fa\u4e86\u96c6\u5408\u8bba\u7684\u516c\u7406\u7cfb\u7edf\u3002</p> <p>\u751f\u8bcd\uff1ahockey\u66f2\u68cd\u7403\uff1bentity\u5b9e\u4f53\uff1bextravagant\u6325\u970d\u7684/\u94fa\u5f20\u6d6a\u8d39\u7684\uff1btrivial\u5e73\u51e1\u7684/\u7410\u788e\u7684/\u5fae\u4e0d\u8db3\u9053\u7684\uff1bmalicious virus\u6076\u610f\u75c5\u6bd2\uff1bdormant\u4f11\u7720\u7684/\u6f5c\u4f0f\u7684\uff1bundermine\u7834\u574f/\u524a\u5f31\u4fe1\u5fc3\uff1birrefutable\u65e0\u53ef\u8fa9\u9a73\u7684\uff1bcrack\u7455\u75b5/\u7f3a\u70b9\uff1berroneous\u9519\u8bef\u7684</p>"},{"location":"Prerequisites/naive_set_theory_1.html#13","title":"1.3 \u516c\u7406\u7cfb\u7edf","text":"<p>\u516c\u7406\u7cfb\u7edf\u7684\u5efa\u7acb\uff1a\uff081\uff09\u58f0\u660e\u539f\u521d\u6216\u672a\u5b9a\u4e49\u6982\u5ff5\uff0c\u5b83\u4eec\u6ca1\u6709\u56fa\u6709\u610f\u4e49\uff0c\u867d\u7136\u8868\u8ff0\u6587\u5b57\u4f1a\u5f15\u8d77\u9605\u8bfb\u8005\u5fc3\u7075\u4e2d\u7684\u76f4\u89c9\u89c2\u5ff5\uff1b\uff082\uff09\u5ba3\u5e03\u6982\u5ff5\u4e4b\u95f4\u5173\u7cfb\u7684\u7279\u522b\u7684\u89c4\u5219\u548c\u6027\u8d28\uff0c\u88ab\u79f0\u4e3a\u201c\u516c\u7406\u201d\u3002</p> <ul> <li>\u6b27\u51e0\u91cc\u5f97\u516c\u7406\u7cfb\u7edf\uff1a\u6b27\u51e0\u91cc\u5f97\u662f\u7b2c\u4e00\u4e2a\u7528\u516c\u7406\u5316\u65b9\u6cd5\u7814\u7a76\u51e0\u4f55\u5b66\u7684\u4eba\u3002\u5728\u4ed6\u7684\u516c\u7406\u7cfb\u7edf\u4e2d\uff1a</li> </ul> <p>\uff081\uff09\u6b27\u51e0\u91cc\u5f97\u5c06\u201c\u70b9\u201d\u548c\u201c\u7ebf\u201d\u5ba3\u5e03\u4e3a\u539f\u521d\u6982\u5ff5\uff1b</p> <p>\uff082\uff09\u6b27\u51e0\u91cc\u5f97\u5c06\u5173\u4e8e\u70b9\u548c\u7ebf\u6027\u8d28\u7684\u63cf\u8ff0\u4f5c\u4e3a\u516c\u7406\uff0c\u8fd9\u4e9b\u516c\u7406\u7684\u9648\u8ff0\u662f\u88ab\u5ba3\u5e03\u4e3a\u81ea\u660e\u800c\u5047\u5b9a\u4e3a\u771f\u7684\uff08\u800c\u975e\u903b\u8f91\u6f14\u7ece\u5f97\u5230\uff09\uff0c\u5b83\u6784\u6210\u4e86\u88ab\u79f0\u4e3a\u201c\u6b27\u51e0\u91cc\u5f97\u51e0\u4f55\u201d\u7684\u8bba\u57df\uff1b</p> <p>\uff083\uff09\u6b27\u51e0\u91cc\u5f97\u7528\u6f14\u7ece\u63a8\u7406\u5f97\u5230\u591a\u79cd\u771f\u7684\u51e0\u4f55\u5b66\u9648\u8ff0\uff0c\u58f0\u79f0\u524d\u63d0\u5b8c\u5168\u6765\u81ea\u4e8ea.\u516c\u7406\u548cb.\u5df2\u5728\u524d\u9762\u8bc1\u660e\u4e3a\u771f\u7684\u9648\u8ff0\u3002</p> <p>\u4e0d\u8fc7\uff0c\u6b27\u51e0\u91cc\u5f97\u8fd8\u662f\u4e0d\u77e5\u4e0d\u89c9\u4f7f\u7528\u4e86\u5728\u516c\u7406\u548c\u4ee5\u8bc1\u5f97\u9648\u8ff0\u4e4b\u5916\u7684\u524d\u63d0\uff0c1899\u5e74\u5927\u536b\u00b7\u5e0c\u5c14\u4f2f\u7279\u4fee\u8ba2\u4e86\u6b27\u51e0\u91cc\u5f97\u516c\u7406\u7cfb\u7edf\u4e3a3\u4e2a\u539f\u521d\u6982\u5ff5\u548c21\u6761\u516c\u7406\uff0c1902\u5e74\u4e00\u6761\u516c\u7406\u88ab\u8ba4\u4e3a\u662f\u591a\u4f59\u7684\u800c\u5220\u9664\u81f320\u6761\u3002</p> <p>\u751f\u8bcd\uff1aintrinsic\u56fa\u6709\u7684/\u5185\u5728\u7684\uff1bscrutiny\u4ed4\u7ec6\u68c0\u67e5\uff1berr\u72af\u9519\u8bef\uff1bredundant\u591a\u4f59\u7684</p>"}]}